<script setup lang="ts">
import { ref, computed } from 'vue';
import { clone } from '../model/domain';
import { blockIssues, blockNames, type ReviewBlock } from '../model/review-content';
import { correctionCandidates } from '../model/review-fixtures';
import WorkbenchDialog from './WorkbenchDialog.vue';
import ReviewSource from './ReviewSource.vue';
import ReviewBlockView from './ReviewBlockView.vue';
const props=defineProps<{value:ReviewBlock;pages:number[];caseId:string}>();
const emit=defineEmits<{save:[value:ReviewBlock];close:[]}>();
const draft=ref(clone(props.value)),error=ref(''),pending=ref(!!props.value.gap),gap=ref(props.value.gap),candidateOpen=ref(false),candidateIndex=ref(0),focusedLine=ref(0);
const candidates=computed(()=>(correctionCandidates[props.caseId]||[]).filter(b=>b.type===draft.value.type&&b.page===draft.value.page));
function adopt(){const value=clone(candidates.value[candidateIndex.value]);if(!value)return;value.id=draft.value.id;draft.value=value;pending.value=!!value.gap;gap.value=value.gap;candidateOpen.value=false;error.value='';}
function close(){if(JSON.stringify(draft.value)!==JSON.stringify(props.value)&&!window.confirm('放弃这次尚未保存的修改？'))return;emit('close');}
function save(){const value=clone(draft.value);value.gap=pending.value?gap.value.trim():'';const issues=blockIssues(value);if(pending.value&&!value.gap){error.value='请说明尚未补齐的内容';return;}if(!pending.value&&issues.length){error.value=issues.join('；');return;}emit('save',value);}
function addColumn(){draft.value.headers.push('');draft.value.rows.forEach(r=>r.push(''));}
function addCategory(){draft.value.chart.categories.push('');draft.value.chart.series.forEach(s=>s.values.push(0));}
function addSeries(){draft.value.chart.series.push({name:'',values:draft.value.chart.categories.map(()=>0),color:'#e28036'});}
function symbol(value:string){const i=focusedLine.value;draft.value.lines[i]=(draft.value.lines[i]||'')+value;}
const shapeNames={circle:'圆',ellipse:'椭圆',triangle:'三角形',square:'正方形',pentagon:'五边形',hexagon:'六边形'};
</script>
<template><WorkbenchDialog :title="'编辑'+blockNames[draft.type]" wide @close="close"><div class="block-edit-grid"><div><ReviewSource :page="draft.page" :pages="pages" :rect="draft.rect" editable @change="(page,rect)=>{draft.page=page;draft.rect=rect}"/><p class="muted">出处随内容保留。框选不会改动原件。</p></div><section class="block-fields">
  <p v-if="error" class="callout danger" role="alert">{{error}}</p>
  <template v-if="draft.type==='text'"><label>文字内容<textarea v-model="draft.text" rows="6"/></label></template>
  <template v-else-if="draft.type==='formula'"><p class="muted">输入 1/3 表示分数；支持数字、字母、四则运算和括号。只检查能否表达，不校正原题的错误运算。</p><div class="button-row"><button v-for="s in ['1/2',' × ',' ÷ ','(',')']" :key="s" class="btn" :aria-label="'插入 '+s" @click="symbol(s)">{{s}}</button></div><div v-for="(_,i) in draft.lines" :key="i" class="formula-input"><label>算式 {{i+1}}<input v-model="draft.lines[i]" @focus="focusedLine=i"/></label><button class="text-link" :aria-label="'删除算式 '+(i+1)" :disabled="draft.lines.length<=1" @click="draft.lines.splice(i,1)">删除</button></div><button class="btn" @click="draft.lines.push('')">增加一行</button><label>结果单位<input v-model="draft.unit" placeholder="如：人。不要填入算式。"/></label></template>
  <template v-else-if="draft.type==='table'"><label>单位<input v-model="draft.unit"/></label><div class="table-scroll"><table class="data-table"><thead><tr><th v-for="(_,i) in draft.headers" :key="i"><input v-model="draft.headers[i]" :aria-label="'表头 '+(i+1)"/></th></tr></thead><tbody><tr v-for="(row,i) in draft.rows" :key="i"><td v-for="(_,j) in row" :key="j"><input v-model="row[j]" :aria-label="'单元格 '+(i+1)+' '+(j+1)" placeholder="留空＝学生待填写"/></td></tr></tbody></table></div><div class="button-row"><button class="btn" @click="draft.rows.push(draft.headers.map(()=>''))">增加行</button><button class="btn" @click="addColumn">增加列</button><button class="text-link" :disabled="draft.rows.length<=1" @click="draft.rows.pop()">删除末行</button><button class="text-link" :disabled="draft.headers.length<=1" @click="draft.headers.pop();draft.rows.forEach(r=>r.pop())">删除末列</button></div><p class="muted">空白表示待填写。看不清的单元格请标记“仍有内容待补”，不能当作空白确认。</p></template>
  <template v-else-if="draft.type==='chart'"><div class="edit-pair"><label>图类型<select aria-label="图类型" v-model="draft.chart.chartType"><option value="bar">分组柱状图</option><option value="line">折线图</option><option value="pie">扇形图（百分比）</option></select></label><label>单位<input v-model="draft.chart.unit" placeholder="亿人 或 %"/></label></div><label>图名<input v-model="draft.chart.title"/></label><div class="table-scroll"><table class="data-table"><thead><tr><th>类别</th><th v-for="(s,j) in draft.chart.series" :key="j"><input v-model="s.name" :aria-label="'系列 '+(j+1)"/></th></tr></thead><tbody><tr v-for="(_,i) in draft.chart.categories" :key="i"><td><input v-model="draft.chart.categories[i]" :aria-label="'类别 '+(i+1)"/></td><td v-for="(s,j) in draft.chart.series" :key="j"><input type="number" step="any" v-model.number="s.values[i]" :aria-label="'数值 '+(i+1)+' '+(j+1)"/></td></tr></tbody></table></div><div class="button-row"><button class="btn" @click="addCategory">增加类别</button><button class="btn" @click="addSeries">增加系列</button><button class="text-link" :disabled="draft.chart.categories.length<=1" @click="draft.chart.categories.pop();draft.chart.series.forEach(s=>s.values.pop())">删除末类别</button><button class="text-link" :disabled="draft.chart.series.length<=1" @click="draft.chart.series.pop()">删除末系列</button></div><details><summary>坐标与显示</summary><div class="edit-pair"><label v-if="draft.chart.chartType!=='pie'">最大值<input type="number" step="any" v-model.number="draft.chart.axis.max"/></label><label v-if="draft.chart.chartType!=='pie'">刻度间隔<input type="number" step="any" v-model.number="draft.chart.axis.step"/></label><label>小数位数<input type="number" min="0" max="4" v-model.number="draft.chart.precision"/></label></div></details></template>
  <template v-else-if="draft.type==='shapes'"><div v-for="(s,i) in draft.shapes" :key="i" class="shape-input"><label>图形 {{i+1}}<select v-model="s.shape"><option v-for="(name,key) in shapeNames" :key="key" :value="key">{{name}}</option></select></label><label>可见标记点<select aria-label="可见标记点" v-model="s.dot"><option value="none">没有</option><option value="center_like">视觉上接近中间</option></select></label><button class="text-link" :disabled="i===0" :aria-label="'上移图形 '+(i+1)" @click="[draft.shapes[i-1],draft.shapes[i]]=[draft.shapes[i],draft.shapes[i-1]]">↑</button><button class="text-link" :disabled="draft.shapes.length<=1" :aria-label="'删除图形 '+(i+1)" @click="draft.shapes.splice(i,1)">删除</button></div><button class="btn" @click="draft.shapes.push({shape:'circle',dot:'none'})">增加图形</button><p class="muted">只表达本轮图形序列。其他几何关系保留缺口，不能用示意图替代已知条件。</p></template>
  <label v-else>尚未表达的内容<textarea v-model="draft.text"/></label>
  <details class="local-extract"><summary>从所选区域重新提取</summary><p class="muted">当前仅载入本例的固定候选（mock），不调用LLM，不自动覆盖。框选区域仍须对照核对。</p><button class="btn" @click="candidateOpen=true;candidateIndex=0">查看提取候选</button><template v-if="candidateOpen"><p v-if="!candidates.length">当前区域没有此类型的预置候选，请手动填写或保留待补。</p><template v-else><label>候选内容<select v-model.number="candidateIndex"><option v-for="(b,i) in candidates" :key="i" :value="i">{{b.type==='chart'?b.chart.title:'候选 '+(i+1)}}</option></select></label><ReviewBlockView :block="candidates[candidateIndex]"/><button class="btn" @click="adopt">采用候选到编辑区</button></template></template></details>
  <section class="edit-preview"><h4>保存后的展示预览</h4><ReviewBlockView :block="{...draft,gap:''}"/></section>
  <label class="check-line"><input type="checkbox" v-model="pending"/>仍有内容待补</label><label v-if="pending">待补原因<textarea v-model="gap" rows="2"/></label>
</section></div><footer class="dialog-footer"><button class="btn" @click="close">取消</button><button class="btn primary" @click="save">{{pending?'保存待补草稿':'保存修改'}}</button></footer></WorkbenchDialog></template>
<style scoped>.block-edit-grid{display:grid;grid-template-columns:minmax(220px,.85fr) minmax(0,1.15fr);gap:22px}.formula-input,.shape-input{display:flex;align-items:center;gap:10px}.formula-input label,.shape-input label{flex:1}.table-scroll{overflow:auto}.table-scroll input{min-width:80px}.edit-preview{border-top:1px solid #e1e8ed;margin-top:22px;padding-top:10px}.local-extract{margin:20px 0;padding:12px;background:#f4f7f5;border-radius:6px}.local-extract summary,details summary{cursor:pointer;color:#2d6a4f}@media(max-width:760px){.block-edit-grid{grid-template-columns:1fr}}</style>
